	"io"
	"strconv"
	"strings"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// jsonTheme is a theme implementation that reads from JSON
type jsonTheme struct {
	colors      map[string]string
	colorsDark  map[string]string
	colorsLight map[string]string
	sizes       map[string]float32
	fonts       map[string]string
	icons       map[string]string
	fallback    fyne.Theme
}

type jsonThemeData struct {
	Colors      map[string]string  `json:"Colors"`
	ColorsDark  map[string]string  `json:"Colors-dark"`
	ColorsLight map[string]string  `json:"Colors-light"`
	Sizes       map[string]float32 `json:"Sizes"`
	Fonts       map[string]string  `json:"Fonts"`
	Icons       map[string]string  `json:"Icons"`
}

// FromJSON parses a JSON string and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSON(data string) (fyne.Theme, error) {
	return FromJSONReader(strings.NewReader(data))
}

// FromJSONReader parses JSON from an io.Reader and returns a Theme.
// On parse error, returns the default theme along with the error.
//
// Since: 2.2
func FromJSONReader(r io.Reader) (fyne.Theme, error) {
	var data jsonThemeData
	decoder := json.NewDecoder(r)
	if err := decoder.Decode(&data); err != nil {
		return DefaultTheme(), err
	}

	theme := &jsonTheme{
		colors:      data.Colors,
		colorsDark:  data.ColorsDark,
		colorsLight: data.ColorsLight,
		sizes:       data.Sizes,
		fonts:       data.Fonts,
		icons:       data.Icons,
		fallback:    DefaultTheme(),
	}

	return theme, nil
}

// Color returns the theme's color for the specified name and variant
func (t *jsonTheme) Color(name fyne.ThemeColorName, variant fyne.ThemeVariant) color.Color {
	// Check variant-specific colors first
	var hexStr string
	var found bool

	if variant == fyne.VariantDark && t.colorsDark != nil {
		hexStr, found = t.colorsDark[string(name)]
	} else if variant == fyne.VariantLight && t.colorsLight != nil {
		hexStr, found = t.colorsLight[string(name)]
	}

	// Fall back to generic colors
	if !found && t.colors != nil {
		hexStr, found = t.colors[string(name)]
	}

	// Parse hex color if found
	if found {
		c, err := parseHexColor(hexStr)
		if err == nil {
			return c
		}
	}

	// Fall back to default theme
	return t.fallback.Color(name, variant)
}

// Font returns the theme's font for the specified style
func (t *jsonTheme) Font(style fyne.TextStyle) fyne.Resource {
	if t.fonts == nil {
		return t.fallback.Font(style)
	}

	var fontName string
	if style.Bold && style.Italic {
		fontName = "boldItalic"
	} else if style.Bold {
		fontName = "bold"
	} else if style.Italic {
		fontName = "italic"
	} else if style.Monospace {
		fontName = "monospace"
	} else {
		fontName = "regular"
	}

	if uriStr, ok := t.fonts[fontName]; ok {
		if uri, err := storage.ParseURI(uriStr); err == nil {
			if res, err := storage.LoadResourceFromURI(uri); err == nil {
				return res
			}
		}
	}

	return t.fallback.Font(style)
}

// Icon returns the theme's icon for the specified icon name
func (t *jsonTheme) Icon(name fyne.ThemeIconName) fyne.Resource {
	if t.icons == nil {
		return t.fallback.Icon(name)
	}

	if uriStr, ok := t.icons[string(name)]; ok {
		if uri, err := storage.ParseURI(uriStr); err == nil {
			if res, err := storage.LoadResourceFromURI(uri); err == nil {
				return res
			}
		}
	}

	return t.fallback.Icon(name)
}

// Size returns the theme's size for the specified size name
func (t *jsonTheme) Size(name fyne.ThemeSizeName) float32 {
	if t.sizes == nil {
		return t.fallback.Size(name)
	}

	if size, ok := t.sizes[string(name)]; ok {
		return size
	}

	return t.fallback.Size(name)
}

// parseHexColor parses a hex color string into a color.Color
// Supports 3, 4, 6, and 8 digit hex formats, with or without # prefix
func parseHexColor(hex string) (color.Color, error) {
	// Remove # prefix if present
	hex = strings.TrimPrefix(hex, "#")

	// Validate hex characters
	for _, c := range hex {
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')) {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
	}

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hex) {
	case 3:
		// RGB format: "abc" -> 0xaa 0xbb 0xcc 0xff
		r = hexDigitToByte(hex[0])
		r = r<<4 | r
		g = hexDigitToByte(hex[1])
		g = g<<4 | g
		b = hexDigitToByte(hex[2])
		b = b<<4 | b

	case 4:
		// RGBA format: "abcd" -> 0xaa 0xbb 0xcc 0xdd
		r = hexDigitToByte(hex[0])
		r = r<<4 | r
		g = hexDigitToByte(hex[1])
		g = g<<4 | g
		b = hexDigitToByte(hex[2])
		b = b<<4 | b
		a = hexDigitToByte(hex[3])
		a = a<<4 | a

	case 6:
		// RRGGBB format: "a1b2c3" -> 0xa1 0xb2 0xc3 0xff
		val, err := strconv.ParseUint(hex, 16, 32)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
		r = uint8((val >> 16) & 0xff)
		g = uint8((val >> 8) & 0xff)
		b = uint8(val & 0xff)

	case 8:
		// RRGGBBAA format: "a1b2c3f4" -> 0xa1 0xb2 0xc3 0xf4
		val, err := strconv.ParseUint(hex, 16, 64)
		if err != nil {
			return color.Transparent, fmt.Errorf("invalid hex color: %s", hex)
		}
		r = uint8((val >> 24) & 0xff)
		g = uint8((val >> 16) & 0xff)
		b = uint8((val >> 8) & 0xff)
		a = uint8(val & 0xff)

	default:
		return color.Transparent, fmt.Errorf("invalid hex color length: %s", hex)
	}

	return color.RGBA{R: r, G: g, B: b, A: a}, nil
}

// hexDigitToByte converts a single hex digit character to its byte value
func hexDigitToByte(c byte) uint8 {
	if c >= '0' && c <= '9' {
		return c - '0'
	}
	if c >= 'a' && c <= 'f' {
		return c - 'a' + 10
	}
	if c >= 'A' && c <= 'F' {
		return c - 'A' + 10
	}
	return 0
}

