package binding

import "fmt"

// stringFromSprintf creates a formatted string binding from any value binding
type stringFromSprintf struct {
	base

	format string
	source DataItem
}

// NewSprintf creates a new String binding that formats the value from the provided source data item
// using fmt.Sprintf with the given format string. The binding updates automatically when the source changes.
// This is useful for combining or formatting data bindings dynamically.
//
// Example:
//   count := binding.NewInt()
//   label := binding.NewSprintf("Count: %d items", count)
//
// Since: 2.2
func NewSprintf(format string, source DataItem) String {
	if source == nil {
		return NewString()
	}

	str := &stringFromSprintf{
		format: format,
		source: source,
	}
	source.AddListener(str)
	return str
}

func (s *stringFromSprintf) Get() (string, error) {
	switch v := s.source.(type) {
	case String:
		val, err := v.Get()
		if err != nil {
			return "", err
		}
		return fmt.Sprintf(s.format, val), nil
	case Int:
		val, err := v.Get()
		if err != nil {
			return "", err
		}
		return fmt.Sprintf(s.format, val), nil
	case Float:
		val, err := v.Get()
		if err != nil {
			return "", err
		}
		return fmt.Sprintf(s.format, val), nil
	case Bool:
		val, err := v.Get()
		if err != nil {
			return "", err
		}
		return fmt.Sprintf(s.format, val), nil
	case Untyped:
		val, err := v.Get()
		if err != nil {
			return "", err
		}
		return fmt.Sprintf(s.format, val), nil
	default:
		return "", fmt.Errorf("unsupported binding type for sprintf")
	}
}

func (s *stringFromSprintf) Set(string) error {
	return fmt.Errorf("sprintf bindings are read-only")
}

func (s *stringFromSprintf) DataChanged() {
	s.trigger()
}

