package validation

import (
	"errors"
	"strings"

	"fyne.io/fyne/v2"
)

// NewAllStrings creates a new validator that requires all of the validators passed as parameters to succeed.
// The validator will return nil if all validators pass, otherwise returns an error combining all failure reasons.
//
// Since: 2.2
func NewAllStrings(validators ...fyne.StringValidator) fyne.StringValidator {
	return func(text string) error {
		var failedReasons []string

		for _, validator := range validators {
			if validator == nil {
				continue
			}

			err := validator(text)
			if err != nil {
				failedReasons = append(failedReasons, err.Error())
			}
		}

		if len(failedReasons) > 0 {
			return errors.New(strings.Join(failedReasons, "; "))
		}

		return nil
	}
}

